entries[385570] = { ["name"] = "Titanengefängnisse", ["text"] = "Sofort\nDie Titanengefängnisse verlieren durch die Angriffe Raszageths und ihrer Streitkräfte der Primalisten an Energie. Bei Erreichen von 0 Energie erleiden die Titanengefängnisse eine katastrophale Fehlfunktion, die allen Spielercharakteren 1000 Arkanschaden zufügt und die Inkarnationen freilässt.\n\nSpielercharaktere können die Energie der Gefängnisse wiederherstellen, indem sie ' Titanische Energie ' auf den titanischen Dynamo auf Iridikrons Plattform übertragen." }
entries[385571] = { ["name"] = "Verbessertes Überwältigen", ["text"] = "'Überwältigen' hat 2 Aufladungen und verursacht 15% mehr Schaden." }
entries[385572] = { ["name"] = "Katastrophale Fehlfunktion", ["text"] = "Sofort\nDie Titanengefängnisse verlieren durch die Angriffe Raszageths und ihrer Streitkräfte der Primalisten an Energie. Bei Erreichen von 0 Energie erleiden die Titanengefängnisse eine katastrophale Fehlfunktion, die allen Spielercharakteren 1000 Arkanschaden zufügt und die Inkarnationen freilässt.\n\nSpielercharaktere können die Energie der Gefängnisse wiederherstellen, indem sie ' Titanische Energie ' auf den titanischen Dynamo auf Iridikrons Plattform übertragen." }
