entries[385574] = { ["name"] = "Orkanschwinge", ["text"] = "Wirken in 3 sek.\nRaszageth schlägt mit den Flügeln nach unten, fügt allen Spielercharakteren 105994 Naturschaden zu und entfesselt eine Sturmwelle. Spielercharaktere in der Sturmwelle fügen anderen Spielercharakteren innerhalb von 6 Metern alle 0.5 Sek. 42398 Naturschaden zu und werden weggestoßen." }
entries[385575] = { ["name"] = "Heulrune", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändig, Fernkämpfer, Fernkämpfer, Schildhand, Waffenhand, Zweihändig\nErfüllt Eure Waffe mit der Energie eines Bakars, was Euer Tempo 2 Stunden lang um 217 erhöht.\n\nFaunarunen können nicht auf Distanzwaffen angewandt werden." }
