entries[385633] = { ["name"] = "Auren der Entschlossenen", ["text"] = "Lehrt Euch 'Aura der Konzentration', 'Aura der Hingabe' und 'Aura des Kreuzfahrers':\n\nAura der Konzentration :\nDie Dauer von Unterbrechungs- und Stilleeffekten bei Gruppen- und Schlachtzugsmitgliedern innerhalb von 40 Metern ist um 30% verringert.\n\nAura der Hingabe :\nGruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern werden durch ihre Hingabe gestärkt, wodurch sich ihr erlittener Schaden um 3% verringert.\n\nAura des Kreuzfahrers :\nErhöht die Reitgeschwindigkeit aller Gruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern um 20%." }
entries[385634] = { ["name"] = "Bewusstlos", ["text"] = "100 Meter Reichweite\nSofort\nMaruuk schwingt seine Waffe und entsendet eine heftige Windböe, die anvisierten Spielercharakteren 15 Naturschaden zufügt und sie wegstößt.\n\nZusätzlich werden anvisierte Spielercharaktere 6 Sek. lang mit ' Bewusstlos ' belegt." }
entries[385635] = { ["name"] = "Kamera des Katalogisierers", ["text"] = "100 Meter Reichweite\nSofort\nErmöglicht Euch, Naturphänomene und Tiere in der Nähe während eines entspannten Ritts zu katalogisieren." }
