entries[385638] = { ["name"] = "Rasiermesserscharfe Pfeilsplitter", ["text"] = "100 Meter Reichweite\nSofort\nNach dem Erhalt von 'Todesstoß' verursacht Euer nächster Einsatz von 'Tödlicher Schuss' 75% mehr Schaden, und bis zu 5 Ziele in der Nähe des Ziels von 'Tödlicher Schuss' erleiden 35% des von 'Tödlicher Schuss' verursachten Schadens im Verlauf von 6 Sek.." }
entries[385639] = { ["name"] = "Auren der schnellen Vergeltung", ["text"] = "Lehrt Euch 'Aura der Vergeltung' und 'Aura des Kreuzfahrers':\n\nAura der Vergeltung :\nWenn ein Gruppen- oder Schlachtzugsmitglied innerhalb von 40 Metern durch einen einzigen Treffer mehr als 30% seiner Gesundheit als Schaden erleidet, werden der verursachte Schaden und die erhaltene Heilung jedes Mitglieds um 5% erhöht. Dieser Effekt lässt im Verlauf von 30 Sek. nach und kann nicht innerhalb von 30 Sek. nach Anwenden der Aura wirksam werden.\n\nAura des Kreuzfahrers :\nErhöht die Reitgeschwindigkeit aller Gruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern um 20%." }
