entries[385881] = { ["name"] = "Lehren der Schwarzen Ernte", ["text"] = "Gebrechen, Zerstörung\nEure Primärdiener erhalten einen Bonuseffekt.\n\nWichtel : Erfolgreiche Einsätze von 'Magie versengen' gewähren dem Ziel 5 Sek. lang 4% Schadensverringerung.\n\nLeerwandler : Verringert die Abklingzeit von 'Schattenbollwerk' um 30 Sek.\n\nTeufelsjäger : Verringert die Abklingzeit von 'Magie verschlingen' um 5 Sek.\n\nSayaad : Verringert die Abklingzeit von 'Verführung' um 10 Sek. und lässt das Ziel schneller in Richtung des Dämons laufen.\n\nDämonologie\nEure Primärdiener erhalten einen Bonuseffekt.\n\nWichtel : Erfolgreiche Einsätze von 'Magie versengen' gewähren dem Ziel 5 Sek. lang 4% Schadensverringerung.\n\nLeerwandler : Verringert die Abklingzeit von 'Schattenbollwerk' um 30 Sek.\n\nTeufelsjäger : Verringert die Abklingzeit von 'Magie verschlingen' um 5 Sek.\n\nSayaad : Verringert die Abklingzeit von 'Verführung' um 10 Sek. und lässt das Ziel schneller in Richtung des Dämons laufen.\n\nTeufelswache : Verringert die Abklingzeit von 'Verfolgung' um 5 Sek. und erhöht die maximale Reichweite der Fähigkeit um 5 Meter." }
