entries[385902] = { ["name"] = "Umbrelskuls gebrochenes Herz", ["text"] = "Ca. 1 Procs pro Minute\nEure Fähigkeiten haben eine Chance, Euer Ziel zu kristallisieren, was ihm [ 173 * (4) * (1 + Vielseitigkeit)] Arkanschaden im Verlauf von 12 Sek. zufügt. Falls das Ziel während der Kristallisierung stirbt, explodiert es und verursacht 1049 Arkanschaden, der auf alle Gegner in der Nähe aufgeteilt wird." }
