entries[385970] = { ["name"] = "Arkane Kugel", ["text"] = "100 Meter Reichweite\nSofort\nDer Professor beschwört aus dem magischen Buch verzauberte Kugeln, die innerhalb von 3 Metern um den Einschlagsort 7273348 Arkanschaden verursachen und dann auf Vexamus zuschweben.\n\nWenn eine Kugel von Vexamus absorbiert wird, erhält der Elementar 20 Energie und fügt allen Spielercharakteren 2917001 Arkanschaden zu. Wenn eine Kugel von einem Spielercharakter absorbiert wird, fügt sie ihm 2431238 Arkanschaden zu." }
entries[385971] = { ["name"] = "Arkane Kugeln", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Professor beschwört aus dem magischen Buch verzauberte Kugeln, die innerhalb von 3 Metern um den Einschlagsort 7273348 Arkanschaden verursachen und dann auf Vexamus zuschweben.\n\nWenn eine Kugel von Vexamus absorbiert wird, erhält der Elementar 20 Energie und fügt allen Spielercharakteren 2917001 Arkanschaden zu. Wenn eine Kugel von einem Spielercharakter absorbiert wird, fügt sie ihm 2431238 Arkanschaden zu." }
entries[385972] = { ["name"] = "Infusion: Frost", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Tobender Frost (2)\nSpezialisierung:\nKöderherstellung - Elementarinfusion\n\nFrosterfüllter Köder für Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n10\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der elementaren Essenz des Frosts erfüllt.\"" }
