entries[385978] = { ["name"] = "Donnervortex", ["text"] = "Unbegrenzte Reichweite\nSofort\nStrunraan löst in einem kreisförmigen Bereich um sich herum Tornados aus, die jeweils 29775 Naturschaden verursachen, den Spielercharakter zurückstoßen und [Strunraans Sturm] anwenden." }
entries[385979] = { ["name"] = "Fluch der Zeitalter", ["text"] = "30 Meter Reichweite\nSofort\nKanalisiert einen Fluch auf ein Ziel, der dessen Körper auf unnatürliche Weise altern lässt. Pro Stapel des Fluchs werden die Bewegungsgeschwindigkeit und das Tempo des Ziels um 2% verringert." }
entries[385980] = { ["name"] = "Donnervortex", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek. 4 sek. Abklingzeit\nStrunraan löst in einem kreisförmigen Bereich um sich herum Tornados aus, die jeweils 29775 Naturschaden verursachen, den Spielercharakter zurückstoßen und [Strunraans Sturm] anwenden." }
entries[385981] = { ["name"] = "Arkane Kugel", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Professor beschwört aus dem magischen Buch verzauberte Kugeln, die innerhalb von 3 Metern um den Einschlagsort 7273348 Arkanschaden verursachen und dann auf Vexamus zuschweben.\n\nWenn eine Kugel von Vexamus absorbiert wird, erhält der Elementar 20 Energie und fügt allen Spielercharakteren 2917001 Arkanschaden zu. Wenn eine Kugel von einem Spielercharakter absorbiert wird, fügt sie ihm 2431238 Arkanschaden zu." }
entries[385982] = { ["name"] = "Infusion: Erde", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Tobende Erde (2)\nSpezialisierung:\nKöderherstellung - Elementarinfusion (10)\n\nErderfüllter Köder für Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n10\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der elementaren Essenz der Erde erfüllt.\"" }
