entries[385984] = { ["name"] = "Infusion: Verfall", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Tobender Verfall (2)\nSpezialisierung:\nKöderherstellung - Elementarinfusion (20)\n\nVerfallerfüllter Köder für Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n10\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der Essenz des Verfalls erfüllt.\"" }
entries[385985] = { ["name"] = "Infusion: Titanisch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Tobende Ordnung (2)\nSpezialisierung:\nKöderherstellung - Elementarinfusion (40)\n\nTitanenerfüllter Köder für Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n10\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der Essenz der Titanen erfüllt.\"" }
