entries[386219] = { ["name"] = "Machtgewinn", ["text"] = "Sofort\nKhajin die Unbeugsame verschießt Hagelschauer auf alle Spielercharaktere, die 80 Frostschaden verursachen und Khajins Energie pro getroffenem Spielercharakter um 10 erhöhen.\n\nEisbrocken blockieren eintreffende Hagelschauer, werden dabei aber beschädigt." }
