entries[386222] = { ["name"] = "Eisbrocken", ["text"] = "Sofort\nDie Frostwoge bildet einen festen Eisbrocken, der zweimal die Effekte von 'Hagelsturm' blocken kann.\n\nNachdem der Brocken das zweite Mal einen solchen Effekt geblockt hat, zerbricht er und verursacht eine Lawine." }
entries[386223] = { ["name"] = "Sturmschild", ["text"] = "Wirken in 0.8 sek.\nDer Zaubernde umgibt sich mit einer Kugel aus Elektrizität, die 12 Sek. lang Schaden bis zu 25% seiner Gesundheit absorbiert.\n\nWenn der Schild abläuft, fügt er Spielercharakteren innerhalb von 60 Metern 2909339 Naturschaden zu." }
